/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const ISU_CD = $c.util.getCookie("ISU_CD");
    const COM_NM = $c.util.getCookie("COM_NM");
    $c.util.getComponent("dma_CalcXhrReq").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_CalcXhrReq").set("COM_NM", COM_NM);
    /* sdd-asis-lifecycle:end */
};


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.pathname = undefined; try { scwin.pathname = /* sdd-asis-lifecycle:begin pathname — as-is 원문 본문(전환 이관 · 포팅 적용됨) */location.pathname/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31208' }); }

scwin.qry = undefined; try { scwin.qry = /* sdd-asis-lifecycle:begin qry — as-is 원문 본문(전환 이관 · 포팅 적용됨) */location.search/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31208' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf31208.onpageload' });
    }
};


